const env=$('Validate Follow-up Envelope').first().json;
const rows=Array.isArray($json)?$json:[$json];
const snap=rows[0];
if(!snap) throw new Error('Runtime snapshot not found');
const schema={
  action:'send|reschedule|handoff|close|skip',
  channel:'whatsapp|email|web_chat|telegram|voice|internal',
  priority:'low|normal|high|urgent',
  reason:'string',
  message:'string|null',
  subject:'string|null',
  lead_stage:'new|contacted|qualified|nurturing|appointment|won|lost|inactive',
  task_status:'completed|scheduled|cancelled|blocked',
  next_follow_up_at:'ISO datetime|null',
  handoff_required:'boolean',
  handoff_reason:'string|null',
  stop_sequence:'boolean',
  memory_facts:[{type:'preference|fact|goal|objection|follow_up',summary:'string',confidence:'0-1'}]
};
return [{json:{
  ...env,
  execution_id:$('Queue Follow-up Execution').first().json.execution_id,
  snapshot:snap,
  provider_request:{
    execution_id:$('Queue Follow-up Execution').first().json.execution_id,
    organization_id:env.organization_id,
    agent_id:env.agent_id,
    instructions:snap.compiled_prompt+'\nDecide the safest next follow-up action using tenant policy, CRM state, prior conversation, customer memory, consent, business hours, and configured channel availability. Never claim a message was sent. Never contact opted-out customers. Return strict JSON only using this schema: '+JSON.stringify(schema),
    input:JSON.stringify({
      event_type:env.event_type,
      channel:env.channel,
      customer:env.input.customer||{},
      lead:env.input.lead||{},
      task:env.input.task||{},
      conversation:env.input.conversation||{},
      follow_up_context:env.input.follow_up_context||env.input
    })
  }
}}];

const ctx=$('Build Follow-up Decision Request').first().json;
let raw=$json.output_text||$json.text||$json.response_text;
if(!raw&&Array.isArray($json.output)) raw=$json.output.flatMap(x=>x.content||[]).map(x=>x.text||x.output_text||'').join('');
raw=String(raw||'').replace(/^```json\s*/i,'').replace(/```$/,'').trim();
let d;
try{d=JSON.parse(raw)}catch(e){throw new Error('Invalid follow-up AI JSON: '+raw.slice(0,300))}
const actions=['send','reschedule','handoff','close','skip'];
const channels=['whatsapp','email','web_chat','telegram','voice','internal'];
const priorities=['low','normal','high','urgent'];
const stages=['new','contacted','qualified','nurturing','appointment','won','lost','inactive'];
const taskStatuses=['completed','scheduled','cancelled','blocked'];
d.action=actions.includes(d.action)?d.action:'skip';
d.channel=channels.includes(d.channel)?d.channel:ctx.channel;
d.priority=priorities.includes(d.priority)?d.priority:'normal';
d.lead_stage=stages.includes(d.lead_stage)?d.lead_stage:'nurturing';
d.task_status=taskStatuses.includes(d.task_status)?d.task_status:(d.action==='send'?'completed':'scheduled');
d.handoff_required=Boolean(d.handoff_required||d.action==='handoff');
d.stop_sequence=Boolean(d.stop_sequence||d.action==='close');
d.memory_facts=Array.isArray(d.memory_facts)?d.memory_facts:[];
if(d.action==='send'&&!String(d.message||'').trim()) throw new Error('Follow-up send action requires message');
return [{json:{...ctx,decision:d,provider_usage:$json.usage||{},provider_response_id:$json.id||null}}];

const r=$json;
const actions=[];
if(r.handoff_required) actions.push({type:'handoff',payload:r.handoff});
if(r.reschedule_action) actions.push({type:'follow_up',payload:r.reschedule_action});
if(r.reply_action) actions.push({type:'reply',payload:r.reply_action});
return [{json:{...r,actions}}];
